{
  "claims": [
    {
      "type": "risk",
      "paragraph_id": "1A-ad221712",
      "quote": "A range of local, state, federal and national laws and regulations currently govern or, in some hydraulic fracturing operations, prohibit hydraulic fracturing in some jurisdictions.",
      "claim": "New and existing laws and regulations governing hydraulic fracturing could increase costs, impose operating restrictions, cause delays, or limit the ability to develop oil and natural gas resources."
    },
    {
      "type": "risk",
      "paragraph_id": "1A-72688255",
      "quote": "In the event that ballot initiatives, local, state, or national restrictions or prohibitions are adopted and result in more stringent limitations on the production and development of oil and natural gas in areas where we conduct operations, we may incur significant costs to comply with such requirements or may experience delays or curtailment in the permitting or pursuit of exploration, development or production activities.",
      "claim": "Adoption of ballot initiatives or other restrictions could impose stricter limits on oil and gas production, leading to significant compliance costs, delays, or curtailments of exploration and development activities."
    }
  ]
}
